export type SparqlTerm = {
  type: "uri" | "literal" | "bnode" | "typed-literal";
  value: string;
  datatype?: string;
  "xml:lang"?: string;
  "its:dir"?: "ltr" | "rtl";
  /** Certified by the connected RDF4J repository transport, never inferred from the label. */
  "rdf4j:reference"?: boolean;
  /** Browser-local document identity for result-only blank nodes. */
  "rdf4j:scope"?: string;
};

const SAFE_LANGUAGE = /^[A-Za-z]+(?:-[A-Za-z0-9]+)*$/;
const SAFE_SPARQL_IRI = /^[A-Za-z][A-Za-z0-9+.-]*:[^<>"{}|^`\\\s]+$/;

export function isSparqlTerm(value: unknown): value is SparqlTerm {
  if (!value || typeof value !== "object") return false;
  const record = value as Record<string, unknown>;
  if (
    record.type !== "uri" &&
    record.type !== "literal" &&
    record.type !== "typed-literal" &&
    record.type !== "bnode"
  ) {
    return false;
  }
  if (typeof record.value !== "string") return false;
  if (record["rdf4j:reference"] !== undefined &&
      (record.type !== "bnode" || typeof record["rdf4j:reference"] !== "boolean")) return false;
  if (record["rdf4j:scope"] !== undefined &&
      (record.type !== "bnode" || typeof record["rdf4j:scope"] !== "string")) return false;
  if (
    record.datatype !== undefined &&
    (typeof record.datatype !== "string" ||
      !SAFE_SPARQL_IRI.test(record.datatype))
  ) return false;
  if (
    record["xml:lang"] !== undefined &&
    (typeof record["xml:lang"] !== "string" ||
      !SAFE_LANGUAGE.test(record["xml:lang"]))
  ) {
    return false;
  }
  if (
    record["its:dir"] !== undefined &&
    record["its:dir"] !== "ltr" &&
    record["its:dir"] !== "rtl"
  ) {
    return false;
  }
  if (
    record.type === "uri" ||
    record.type === "bnode"
  ) {
    if (record.datatype !== undefined || record["xml:lang"] !== undefined) {
      return false;
    }
  }
  if (record.datatype !== undefined && record["xml:lang"] !== undefined) {
    return false;
  }
  if (
    record["its:dir"] !== undefined &&
    (record.type !== "literal" || !record["xml:lang"] || record.datatype !== undefined)
  ) {
    return false;
  }
  if (
    record.type === "typed-literal" &&
    (typeof record.datatype !== "string" || !record.datatype)
  ) {
    return false;
  }
  return true;
}

export const INTERNAL_LITERAL_NODE_PREFIX = "__rdf_literal__:";
export const INTERNAL_BNODE_NODE_PREFIX = "__rdf_bnode__:";
export const INTERNAL_SCOPED_BNODE_NODE_PREFIX = "__rdf_scoped_bnode__:";
/** A fresh document namespace, including on ordinary HTTP where randomUUID is unavailable. */
export function blankNodeDocumentScope() {
  const nonce = crypto.getRandomValues(new Uint32Array(4));
  return Array.from(nonce, value => value.toString(16).padStart(8, "0")).join("");
}
const RDF_LANG_STRING =
  "http://www.w3.org/1999/02/22-rdf-syntax-ns#langString";


export function isSafeSparqlIri(value: string) {
  return SAFE_SPARQL_IRI.test(value);
}

function escapedSparqlString(value: string) {
  return value
    .replace(/\\/g, "\\\\")
    .replace(/"/g, '\\"')
    .replace(/\r/g, "\\r")
    .replace(/\n/g, "\\n")
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, unicodeEscape);
}

function unicodeEscape(value: string) {
  return "\\u" + value.charCodeAt(0).toString(16).toUpperCase().padStart(4, "0");
}

/** A repository-local query operand. The input is a raw ID, including an empty ID or a leading `_:`. */
export function fixedBlankNodeReference(rawId: string) {
  for (const character of rawId) {
    const scalar = character.codePointAt(0)!;
    if (scalar >= 0xd800 && scalar <= 0xdfff) throw new Error("Invalid Unicode surrogate in blank-node identifier.");
  }
  return `<_:${rawId.replace(/[\u0000-\u0020<>"{}|^`\\\u007f-\u009f]/g, unicodeEscape)}>`;
}

/** Decode Unicode escapes exactly once. An ordinary _:label is never a fixed reference. */
export function parseFixedBlankNodeReference(value: string): SparqlTerm | undefined {
  if (!value.startsWith("<_:") || !value.endsWith(">")) return undefined;
  const encoded = value.slice(3, -1);
  let raw = "";
  for (let index = 0; index < encoded.length; index++) {
    const character = encoded[index];
    if (character === "\\") {
      const size = encoded[index + 1] === "u" ? 4 : encoded[index + 1] === "U" ? 8 : 0;
      const hex = encoded.slice(index + 2, index + 2 + size);
      if (!size || hex.length !== size || !/^[0-9a-f]+$/i.test(hex)) return undefined;
      const code = Number.parseInt(hex, 16);
      if (code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) return undefined;
      raw += String.fromCodePoint(code);
      index += size + 1;
    } else {
      if (/[\u0000-\u0020<>"{}|^`]/.test(character)) return undefined;
      const scalar = encoded.codePointAt(index)!;
      if (scalar >= 0xd800 && scalar <= 0xdfff) return undefined;
      raw += String.fromCodePoint(scalar);
      if (scalar > 0xffff) index++;
    }
  }
  return { type: "bnode", value: raw, "rdf4j:reference": true };
}

/** URI and certified blank-node graph IDs only; predicates still use the stricter IRI codec. */
export function sparqlResourceToken(nodeId: string): string | null {
  const blank = parseFixedBlankNodeReference(nodeId);
  if (blank) return fixedBlankNodeReference(blank.value);
  return isSafeSparqlIri(nodeId) ? `<${nodeId}>` : null;
}

export function isQueryableResource(nodeId: string) {
  return sparqlResourceToken(nodeId) !== null;
}

/** Normalize a user-entered resource, accepting an absolute IRI or a fixed blank reference. */
export function resourceNodeId(value: string): string | undefined {
  const blank = parseFixedBlankNodeReference(value);
  if (blank) return sparqlNodeId(blank);
  const iri = value.startsWith("<") && value.endsWith(">") ? value.slice(1, -1) : value;
  return isSafeSparqlIri(iri) ? iri : undefined;
}

export function sparqlNodeId(term: SparqlTerm) {
  if (term.type === "uri") return term.value;
  if (term.type === "bnode") {
    if (term["rdf4j:reference"] === true) return fixedBlankNodeReference(term.value);
    if (term["rdf4j:scope"] !== undefined)
      return `${INTERNAL_SCOPED_BNODE_NODE_PREFIX}${JSON.stringify([term["rdf4j:scope"], term.value])}`;
    return `${INTERNAL_BNODE_NODE_PREFIX}${term.value}`;
  }
  const language = term["xml:lang"]?.trim().toLocaleLowerCase() ?? "";
  const datatype =
    language && term.datatype === RDF_LANG_STRING ? "" : term.datatype ?? "";
  const identity = {
    type: term.type,
    value: term.value,
    datatype,
    language,
    ...(term["its:dir"] !== undefined ? { direction: term["its:dir"] } : {}),
  };
  return `${INTERNAL_LITERAL_NODE_PREFIX}${JSON.stringify(identity)}`;
}

export function sparqlTermFromNodeId(nodeId: string): SparqlTerm | undefined {
  const reference = parseFixedBlankNodeReference(nodeId);
  if (reference) return reference;
  if (nodeId.startsWith(INTERNAL_SCOPED_BNODE_NODE_PREFIX)) {
    try {
      const scoped = JSON.parse(nodeId.slice(INTERNAL_SCOPED_BNODE_NODE_PREFIX.length));
      if (Array.isArray(scoped) && scoped.length === 2 && scoped.every(v => typeof v === "string"))
        return {type: "bnode", value: scoped[1], "rdf4j:scope": scoped[0]};
    } catch { /* Malformed document identity. */ }
    return undefined;
  }
  if (nodeId.startsWith(INTERNAL_BNODE_NODE_PREFIX)) {
    const value = nodeId.slice(INTERNAL_BNODE_NODE_PREFIX.length);
    return {
      type: "bnode",
      value,
    };
  }
  if (nodeId.startsWith(INTERNAL_LITERAL_NODE_PREFIX)) {
    try {
      const parsed: unknown = JSON.parse(
        nodeId.slice(INTERNAL_LITERAL_NODE_PREFIX.length),
      );
      if (!parsed || typeof parsed !== "object") return undefined;
      const record = parsed as Record<string, unknown>;
      if (
        (record.type !== "literal" && record.type !== "typed-literal") ||
        typeof record.value !== "string" ||
        (record.datatype !== "" && typeof record.datatype !== "string") ||
        (record.language !== "" && typeof record.language !== "string") ||
        (record.direction !== undefined && record.direction !== "ltr" && record.direction !== "rtl")
      ) {
        return undefined;
      }
      const term: SparqlTerm = {
        type: record.type,
        value: record.value,
      };
      if (record.datatype) term.datatype = record.datatype;
      if (record.language) term["xml:lang"] = record.language;
      if (record.direction === "ltr" || record.direction === "rtl") term["its:dir"] = record.direction;
      return isSparqlTerm(term) ? term : undefined;
    } catch {
      return undefined;
    }
  }
  return isSafeSparqlIri(nodeId)
    ? { type: "uri", value: nodeId }
    : undefined;
}

/**
 * Convert a canonical graph node ID back into a safe SPARQL VALUES token.
 * Ordinary `_:` labels and uncertified document IDs cannot name an existing node. Certified fixed references can.
 */
export function sparqlFacetValueToken(nodeId: string): string | null {
  const term = sparqlTermFromNodeId(nodeId);
  if (!term) return null;
  if (term.type === "uri") return `<${term.value}>`;
  if (term.type === "bnode") return term["rdf4j:reference"] === true ? fixedBlankNodeReference(term.value) : null;
  const value = `"${escapedSparqlString(term.value)}"`;
  if (term["xml:lang"] && SAFE_LANGUAGE.test(term["xml:lang"])) {
    return `${value}@${term["xml:lang"]}${term["its:dir"] ? `--${term["its:dir"]}` : ""}`;
  }
  if (term.datatype && isSafeSparqlIri(term.datatype)) {
    return `${value}^^<${term.datatype}>`;
  }
  return value;
}

export function sparqlTermValue(nodeId: string) {
  return sparqlTermFromNodeId(nodeId)?.value;
}
